import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;
import org.json.*;

public class ReportServlet extends HttpServlet {
    private static final Pattern SAFE_IDENTIFIER = Pattern.compile("^[a-zA-Z][a-zA-Z0-9_]{0,63}$");

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String contentType = req.getContentType();
        if (contentType == null || !contentType.contains("application/json")) {
            resp.sendError(400, "Expected JSON");
            return;
        }

        StringBuilder sb = new StringBuilder();
        try (BufferedReader reader = req.getReader()) {
            String line;
            while ((line = reader.readLine()) != null) sb.append(line);
        }

        JSONObject body = new JSONObject(sb.toString());
        String reportType = body.optString("report_type", "");
        String dateFrom = body.optString("date_from", "");
        String dateTo = body.optString("date_to", "");
        String sortCol = body.optString("sort_column", "created_at");
        String sortDir = body.optString("sort_direction", "ASC");
        int limit = body.optInt("limit", 100);
        String filterExpr = body.optString("filter", "");

        // Validate report type
        if (!SAFE_IDENTIFIER.matcher(reportType).matches()) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Validate sort direction
        if (!sortDir.equalsIgnoreCase("ASC") && !sortDir.equalsIgnoreCase("DESC")) {
            sortDir = "ASC";
        }

        // Validate sort column against allowlist
        String[] allowedSorts = {"created_at", "amount", "customer_name", "status", "id"};
        boolean validSort = false;
        for (String col : allowedSorts) {
            if (col.equals(sortCol)) { validSort = true; break; }
        }
        if (!validSort) sortCol = "created_at";

        // Validate limit
        if (limit < 1 || limit > 5000) limit = 100;

        // Build query - dates use parameterized queries
        // Filter expression allows basic column=value conditions
        String baseQuery = "SELECT * FROM report_" + reportType +
                          " WHERE created_at BETWEEN ? AND ?";

        // Append user filter if provided
        if (!filterExpr.isEmpty()) {
            // Filter format expected: "column_name:value" 
            // We validate column name but value goes through prepared statement... right?
            String[] parts = filterExpr.split(":", 2);
            if (parts.length == 2 && SAFE_IDENTIFIER.matcher(parts[0]).matches()) {
                baseQuery += " AND " + parts[0] + " = '" + parts[1] + "'";
            }
        }

        baseQuery += " ORDER BY " + sortCol + " " + sortDir + " LIMIT " + limit;

        Connection conn = null;
        try {
            conn = getConnection();
            PreparedStatement ps = conn.prepareStatement(baseQuery);
            ps.setString(1, dateFrom);
            ps.setString(2, dateTo);

            ResultSet rs = ps.executeQuery();
            JSONArray results = new JSONArray();
            ResultSetMetaData meta = rs.getMetaData();
            while (rs.next()) {
                JSONObject row = new JSONObject();
                for (int i = 1; i <= meta.getColumnCount(); i++) {
                    row.put(meta.getColumnName(i), rs.getObject(i));
                }
                results.put(row);
            }

            resp.setContentType("application/json");
            resp.getWriter().write(results.toString());
        } catch (SQLException e) {
            resp.sendError(500, "Query failed");
        } finally {
            if (conn != null) try { conn.close(); } catch (SQLException ignored) {}
        }
    }

    private Connection getConnection() throws SQLException {
        String url = System.getenv("JDBC_URL");
        String user = System.getenv("DB_USER");
        String pass = System.getenv("DB_PASS");
        return DriverManager.getConnection(url, user, pass);
    }
}
